    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #020617;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #020617;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #020617;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root { background-color: #020617; }\n      #stage { position: absolute; inset: 0; }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"particles-grid\"\n      data-start=\"0\"\n      data-duration=\"6.67\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"6.67\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const view = hyperbits.viewport();\n        const canvas = document.getElementById(\"stage\");\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const cols = 16;\n        const rows = 9;\n        const cellW = view.width / cols;\n        const cellH = view.height / rows;\n        const simulator = hyperbits.createParticles({\n          fps: 30,\n          spawners: [{\n            id: \"scatter\",\n            burst: cols * rows,\n            position: { x: view.width / 2, y: view.height / 2 },\n            area: { width: view.width, height: view.height },\n            velocity: { x: 0, y: 0, varianceX: 8, varianceY: 8 },\n            lifespan: 200,\n          }],\n          behaviors: [{\n            id: \"snap\",\n            handler: function (particle) {\n              const col = particle.index % cols;\n              const row = Math.floor(particle.index / cols);\n              const targetX = cellW * (col + 0.5);\n              const targetY = cellH * (row + 0.5);\n              particle.velocity.x += (targetX - particle.position.x) * 0.04;\n              particle.velocity.y += (targetY - particle.position.y) * 0.04;\n              particle.velocity.x *= 0.86;\n              particle.velocity.y *= 0.86;\n            },\n          }],\n        });\n        const timeline = gsap.timeline({ paused: true });\n        hyperbits.bind(timeline, canvas, simulator, { color: \"#38bdf8\", size: view.vmin * 1.6 });\n        timeline.to({}, { duration: 6.67 }, 0);\n        registerTimeline(\"particles-grid\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
