    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #020617;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #020617;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #020617;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root { perspective: 1400px; background-color: #020617; overflow: hidden; }\n      #world { position: absolute; inset: 0; transform-style: preserve-3d; }\n      .col { position: absolute; top: -40%; height: 180%; display: flex; flex-direction: column; gap: 18px; }\n      .card { border-radius: 18px; flex: 0 0 auto; }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"scrolling-columns\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"world\" class=\"clip\" data-start=\"0\" data-duration=\"10\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const view = hyperbits.viewport();\n        const world = document.getElementById(\"world\");\n        const palette = [\"#1d4ed8\", \"#0f766e\", \"#9a3412\", \"#6d28d9\", \"#be123c\", \"#0369a1\"];\n        const speeds = [0.35, 0.55, 0.28, 0.7];\n        const columns = [];\n        for (let col = 0; col < 4; col += 1) {\n          const column = document.createElement(\"div\");\n          column.className = \"col\";\n          column.style.left = 10 + col * 22 + \"%\";\n          column.style.width = \"18%\";\n          const depth = col % 2 === 0 ? -120 : 80;\n          for (let cardIndex = 0; cardIndex < 10; cardIndex += 1) {\n            const card = document.createElement(\"div\");\n            card.className = \"card\";\n            card.style.height = view.vh * 22 + \"px\";\n            card.style.backgroundColor = palette[hyperbits.randomInt(\"c-\" + col + \"-\" + cardIndex, 0, palette.length - 1)];\n            column.append(card);\n          }\n          world.append(column);\n          columns.push({ el: column, speed: speeds[col], depth: depth });\n        }\n        const proxy = { t: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, {\n          t: 10,\n          duration: 10,\n          ease: \"none\",\n          onUpdate: function () {\n            world.style.transform = \"rotateY(\" + (proxy.t * 3 - 12) + \"deg) translateZ(\" + view.vmin * 4 + \"px)\";\n            columns.forEach(function (column) {\n              column.el.style.transform =\n                \"translateZ(\" +\n                column.depth +\n                \"px) translateY(\" +\n                -proxy.t * column.speed * view.vh * 8 +\n                \"px)\";\n            });\n          },\n        }, 0);\n        registerTimeline(\"scrolling-columns\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
