    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #020617;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #020617;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #020617;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root { background-color: #020617; }\n      .face {\n        width: 320px; height: 320px; display: flex; align-items: center; justify-content: center;\n        color: #f8fafc; font-weight: 800; border: 2px solid rgba(248,250,252,0.2);\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"cube-navigation\"\n      data-start=\"0\"\n      data-duration=\"16\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const view = hyperbits.viewport();\n        const root = document.getElementById(\"root\");\n        const size = view.vmin * 28;\n        const half = size / 2;\n        const faces = [\n          { name: \"Front\", color: \"#1d4ed8\", x: 0, y: 0, z: half, rotateY: 0 },\n          { name: \"Right\", color: \"#0f766e\", x: half, y: 0, z: 0, rotateY: 90 },\n          { name: \"Back\", color: \"#9a3412\", x: 0, y: 0, z: -half, rotateY: 180 },\n          { name: \"Left\", color: \"#6d28d9\", x: -half, y: 0, z: 0, rotateY: -90 },\n          { name: \"Top\", color: \"#be123c\", x: 0, y: -half, z: 0, rotateX: 90 },\n          { name: \"Bottom\", color: \"#0369a1\", x: 0, y: half, z: 0, rotateX: -90 },\n        ];\n        const elements = faces.map(function (face) {\n          const node = document.createElement(\"div\");\n          node.className = \"face\";\n          node.setAttribute(\"data-layout-allow-overlap\", \"\");\n          node.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          node.textContent = face.name;\n          node.style.width = size + \"px\";\n          node.style.height = size + \"px\";\n          node.style.backgroundColor = face.color;\n          node.style.fontSize = view.vmin * 4 + \"px\";\n          return { element: node, x: face.x, y: face.y, z: face.z, rotateX: face.rotateX || 0, rotateY: face.rotateY || 0 };\n        });\n        const scene = hyperbits.createScene3D(root, {\n          perspective: 1600,\n          transitionDuration: 0.9,\n          stepDuration: 16 / 6,\n          steps: [\n            { id: \"front\", rotateY: 0, z: view.vmin * 10 },\n            { id: \"right\", rotateY: -90, z: view.vmin * 10 },\n            { id: \"back\", rotateY: -180, z: view.vmin * 10 },\n            { id: \"left\", rotateY: -270, z: view.vmin * 10 },\n            { id: \"top\", rotateX: -90, z: view.vmin * 10 },\n            { id: \"bottom\", rotateX: 90, z: view.vmin * 10 },\n          ],\n          elements: elements,\n        });\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        timeline.to({}, { duration: 16 }, 0);\n        registerTimeline(\"cube-navigation\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
