    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0b1220;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0b1220;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #0b1220;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root { background-color: #0b1220; }\n      #screen {\n        width: 960px; height: 600px; background-color: #111827; border-radius: 28px;\n        border: 1px solid #334155; position: relative; overflow: hidden;\n      }\n      .widget { position: absolute; border-radius: 16px; background-color: #1e293b; color: #e2e8f0; padding: 18px 22px; font-weight: 600; }\n      #cursor {\n        position: absolute; width: 28px; height: 28px; z-index: 5;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"cursor-flyover\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const view = hyperbits.viewport();\n        const root = document.getElementById(\"root\");\n        const screen = document.createElement(\"div\");\n        screen.id = \"screen\";\n        const widgets = [\n          { label: \"Revenue\", x: \"8%\", y: \"12%\", w: \"28%\" },\n          { label: \"Active users\", x: \"40%\", y: \"12%\", w: \"24%\" },\n          { label: \"Pipeline\", x: \"8%\", y: \"48%\", w: \"56%\" },\n          { label: \"Alerts\", x: \"68%\", y: \"12%\", w: \"24%\" },\n        ];\n        widgets.forEach(function (widget) {\n          const node = document.createElement(\"div\");\n          node.className = \"widget\";\n          node.textContent = widget.label;\n          node.style.left = widget.x;\n          node.style.top = widget.y;\n          node.style.width = widget.w;\n          screen.append(node);\n        });\n        const cursor = document.createElementNS(\"http://www.w3.org/2000/svg\", \"svg\");\n        cursor.setAttribute(\"id\", \"cursor\");\n        cursor.setAttribute(\"viewBox\", \"0 0 24 24\");\n        const path = document.createElementNS(\"http://www.w3.org/2000/svg\", \"path\");\n        path.setAttribute(\"d\", \"M3 3l8 18 2-7 7-2z\");\n        path.setAttribute(\"fill\", \"#f8fafc\");\n        cursor.append(path);\n        screen.append(cursor);\n        const scene = hyperbits.createScene3D(root, {\n          perspective: 1400,\n          transitionDuration: 1.1,\n          stepDuration: 2.5,\n          steps: [\n            { id: \"wide\", z: view.vmin * 8, rotateX: 8, element: screen },\n            { id: \"rev\", x: -view.vmin * 10, y: -view.vmin * 6, z: view.vmin * 30 },\n            { id: \"pipe\", y: view.vmin * 8, z: view.vmin * 24, rotateX: 4 },\n            { id: \"alerts\", x: view.vmin * 14, z: view.vmin * 28 },\n          ],\n        });\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        timeline.fromTo(cursor, { x: 40, y: 40 }, { x: 120, y: 70, duration: 2.2, ease: \"power2.inOut\" }, 0.4);\n        timeline.to(cursor, { x: 220, y: 260, duration: 2.4, ease: \"power2.inOut\" }, 2.8);\n        timeline.to(cursor, { x: 620, y: 80, duration: 2.2, ease: \"power2.inOut\" }, 5.4);\n        timeline.to({}, { duration: 10 }, 0);\n        registerTimeline(\"cursor-flyover\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
