    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"words\",\"type\":\"string\",\"label\":\"Words\",\"default\":\"SEEK,FRAME,MOTION,SCALE,DEPTH,LIGHT,TIME,SPACE\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #000000;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #000000;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #000000;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root { background-color: #000000; }\n      .word { color: #e2e8f0; font-weight: 800; letter-spacing: 0.08em; white-space: nowrap; }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"flying-through-words\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const view = hyperbits.viewport();\n        const root = document.getElementById(\"root\");\n        const words = String(vars.words).split(\",\").map(function (part) { return part.trim(); });\n        const elements = [];\n        for (let index = 0; index < 24; index += 1) {\n          const node = document.createElement(\"div\");\n          node.className = \"word\";\n          node.setAttribute(\"data-layout-allow-overlap\", \"\");\n          node.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          node.textContent = words[index % words.length];\n          node.style.fontSize = view.vmin * hyperbits.randomFloat(\"fs-\" + index, 3, 8) + \"px\";\n          elements.push({\n            element: node,\n            x: hyperbits.randomFloat(\"x-\" + index, -view.vmin * 40, view.vmin * 40),\n            y: hyperbits.randomFloat(\"y-\" + index, -view.vmin * 24, view.vmin * 24),\n            z: hyperbits.randomFloat(\"z-\" + index, -view.vmin * 10, view.vmin * 220),\n          });\n        }\n        const scene = hyperbits.createScene3D(root, {\n          perspective: 900,\n          transitionDuration: 2,\n          steps: [\n            { id: \"start\", z: 0, duration: 1 },\n            { id: \"fly\", z: view.vmin * 180, duration: 9 },\n          ],\n          elements: elements,\n        });\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        timeline.to({}, { duration: 10 }, 0);\n        registerTimeline(\"flying-through-words\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
