    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0f172a;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0f172a;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #0f172a;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root { background-color: #0f172a; }\n      .slide { color: #f8fafc; width: 900px; }\n      h1 { font-weight: 800; }\n      p { color: #cbd5e1; margin-top: 0.4em; }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"step-timing-context\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const view = hyperbits.viewport();\n        const root = document.getElementById(\"root\");\n        function slide(titleText, bodyText) {\n          const wrap = document.createElement(\"div\");\n          wrap.className = \"slide\";\n          const title = document.createElement(\"h1\");\n          title.textContent = titleText;\n          title.style.fontSize = view.vmin * 6 + \"px\";\n          const body = document.createElement(\"p\");\n          body.textContent = bodyText;\n          body.style.fontSize = view.vmin * 2.6 + \"px\";\n          wrap.append(title, body);\n          return wrap;\n        }\n        const first = slide(\"Enter\", \"Copy reveals as the camera settles.\");\n        const second = slide(\"Hold\", \"Motion waits for the active step.\");\n        const third = slide(\"Leave\", \"Exit starts before the next camera move.\");\n        const scene = hyperbits.createScene3D(root, {\n          perspective: 1100,\n          transitionDuration: 0.8,\n          stepDuration: 3.2,\n          steps: [\n            { id: \"enter\", x: 0, z: 0, element: first },\n            { id: \"hold\", x: view.vmin * 40, rotateY: -12, element: second },\n            { id: \"leave\", x: view.vmin * 80, rotateY: 12, element: third },\n          ],\n        });\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        [first, second, third].forEach(function (node, index) {\n          const words = hyperbits.splitText(node.querySelector(\"h1\"), \"words\");\n          hyperbits.stagger(words, { opacity: [0, 1], y: [16, 0], duration: 0.45, stagger: 0.06, delay: index * 3.2 }, timeline);\n        });\n        timeline.to({}, { duration: 10 }, 0);\n        registerTimeline(\"step-timing-context\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
