    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0b1220;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0b1220;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #0b1220;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root { display: flex; align-items: center; justify-content: center; background-color: #0b1220; }\n      #thread { display: flex; flex-direction: column; }\n      .bubble { max-width: 70%; padding: 0.7em 1em; border-radius: 1.2em; font-weight: 500; }\n      .me { align-self: flex-end; background-color: #2563eb; color: #eff6ff; border-bottom-right-radius: 0.3em; }\n      .them { align-self: flex-start; background-color: #1f2937; color: #e5e7eb; border-bottom-left-radius: 0.3em; }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"chat-conversation\"\n      data-start=\"0\"\n      data-duration=\"5\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"thread\" class=\"clip\" data-start=\"0\" data-duration=\"5\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const view = hyperbits.viewport();\n        const thread = document.getElementById(\"thread\");\n        thread.style.width = view.vw * 42 + \"px\";\n        thread.style.gap = view.vmin * 1.8 + \"px\";\n        thread.style.fontSize = view.vmin * 2.6 + \"px\";\n        const messages = [\n          { who: \"them\", text: \"Did the render finish?\" },\n          { who: \"me\", text: \"Just exported the 1080p master.\" },\n          { who: \"them\", text: \"How is the motion on the lower third?\" },\n          { who: \"me\", text: \"Seek-safe now. Try scrubbing it.\" },\n          { who: \"them\", text: \"Nice. Ship it.\" },\n        ];\n        for (const message of messages) {\n          const bubble = document.createElement(\"div\");\n          bubble.className = \"bubble \" + message.who;\n          bubble.textContent = message.text;\n          thread.append(bubble);\n        }\n        const timeline = gsap.timeline({ paused: true });\n        hyperbits.stagger(thread.children, { opacity: [0, 1], y: [24, 0], duration: 0.45, stagger: 0.55, ease: \"power2.out\" }, timeline);\n        registerTimeline(\"chat-conversation\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
