    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #020617;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #020617;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #020617;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root { background-color: #020617; }\n      #stage { position: absolute; inset: 8%; }\n      .tile { position: absolute; border-radius: 18px; overflow: hidden; }\n      .swatch { width: 100%; height: 100%; }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"mosaic-reframe\"\n      data-start=\"0\"\n      data-duration=\"9\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"9\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const view = hyperbits.viewport();\n        const stage = document.getElementById(\"stage\");\n        const colors = [\"#0ea5e9\", \"#6366f1\", \"#f43f5e\", \"#f59e0b\", \"#22c55e\", \"#14b8a6\", \"#e879f9\", \"#94a3b8\", \"#f97316\", \"#38bdf8\", \"#a3e635\", \"#f472b6\"];\n        const tiles = [];\n        for (let index = 0; index < 12; index += 1) {\n          const tile = document.createElement(\"div\");\n          tile.className = \"tile\";\n          const swatch = document.createElement(\"div\");\n          swatch.className = \"swatch\";\n          swatch.style.backgroundColor = colors[index];\n          tile.append(swatch);\n          stage.append(tile);\n          tiles.push(tile);\n        }\n        const stageWidth = view.width * 0.84;\n        const stageHeight = view.height * 0.84;\n        const baseW = stageWidth * 0.22;\n        const baseH = stageHeight * 0.26;\n        function gridPos(index) {\n          const col = index % 4;\n          const row = Math.floor(index / 4);\n          return { x: col * 24, y: row * 30, w: 22, h: 26 };\n        }\n        function featurePos(index) {\n          if (index === 0) return { x: 0, y: 0, w: 46, h: 62 };\n          if (index < 5) return { x: 50, y: (index - 1) * 16, w: 22, h: 14 };\n          return { x: 76, y: (index - 5) * 12, w: 22, h: 10 };\n        }\n        function cascadePos(index) {\n          return { x: 8 + index * 6, y: 8 + index * 6, w: 18, h: 22 };\n        }\n        function toMotion(box) {\n          return {\n            x: (box.x / 100) * stageWidth,\n            y: (box.y / 100) * stageHeight,\n            scaleX: box.w / 22,\n            scaleY: box.h / 26,\n          };\n        }\n        tiles.forEach(function (tile, index) {\n          const start = toMotion(gridPos(index));\n          gsap.set(tile, {\n            width: baseW,\n            height: baseH,\n            transformOrigin: \"0 0\",\n            x: start.x,\n            y: start.y,\n            scaleX: start.scaleX,\n            scaleY: start.scaleY,\n          });\n        });\n        const timeline = gsap.timeline({ paused: true });\n        tiles.forEach(function (tile, index) {\n          const start = toMotion(gridPos(index));\n          const feature = toMotion(featurePos(index));\n          const cascade = toMotion(cascadePos(index));\n          timeline.fromTo(\n            tile,\n            { opacity: 0, scaleX: start.scaleX * 0.8, scaleY: start.scaleY * 0.8 },\n            { opacity: 1, scaleX: start.scaleX, scaleY: start.scaleY, duration: 0.45, ease: \"power2.out\" },\n            index * 0.04,\n          );\n          timeline.to(tile, {\n            x: feature.x,\n            y: feature.y,\n            scaleX: feature.scaleX,\n            scaleY: feature.scaleY,\n            duration: 1.1,\n            ease: \"power3.inOut\",\n          }, 2.2);\n          timeline.to(tile, {\n            x: cascade.x,\n            y: cascade.y,\n            scaleX: cascade.scaleX,\n            scaleY: cascade.scaleY,\n            duration: 1.1,\n            ease: \"power3.inOut\",\n          }, 5.4);\n        });\n        registerTimeline(\"mosaic-reframe\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
