    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"command\",\"type\":\"string\",\"label\":\"Command\",\"default\":\"npm install hyperbits\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #1e1e1e;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #1e1e1e;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #1e1e1e;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root {\n        display: flex;\n        justify-content: center;\n        background-color: #1e1e1e;\n        font-family: ui-monospace, monospace;\n        color: #d4d4d4;\n      }\n      #term {\n        width: 86%;\n        margin-top: 8%;\n        line-height: 1.55;\n      }\n      .row { display: flex; gap: 0.6em; }\n      .ok { color: #4ec9b0; }\n      .path { color: #569cd6; }\n      .cmd { color: #ce9178; }\n      .out { color: #d4d4d4; white-space: pre-wrap; }\n      #cursor { width: 0.55em; background-color: #d4d4d4; }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"cli-simulation\"\n      data-start=\"0\"\n      data-duration=\"15\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"term\" class=\"clip\" data-start=\"0\" data-duration=\"15\">\n        <div class=\"row\">\n          <span class=\"ok\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#4ec9b0\" stroke-width=\"2.4\"><path d=\"M5 12h14\"/><path d=\"M13 6l6 6-6 6\"/></svg>\n          </span>\n          <span class=\"path\">~</span>\n          <span id=\"command\" class=\"cmd\"></span>\n          <span id=\"cursor\">&nbsp;</span>\n        </div>\n        <div id=\"output\" class=\"out\"></div>\n      </div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const view = hyperbits.viewport();\n        const term = document.getElementById(\"term\");\n        const commandEl = document.getElementById(\"command\");\n        const outputEl = document.getElementById(\"output\");\n        const cursor = document.getElementById(\"cursor\");\n        term.style.fontSize = view.vmin * 3 + \"px\";\n        const command = String(vars.command);\n        commandEl.textContent = command;\n        const commandWriter = hyperbits.typewriter(commandEl, { duration: 100 / 30, delay: 0 });\n        const logs = [\"Package found\", \"Dependencies resolved\", \"Installing...\", \"Done in 1.4s\"];\n        outputEl.textContent = logs.map(function (line) { return \"  \" + line; }).join(\"\\n\");\n        const outputWriter = hyperbits.typewriter(outputEl, { duration: 2.4, delay: 90 / 30 });\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, {\n          time: 15,\n          duration: 15,\n          ease: \"none\",\n          onUpdate: function () {\n            commandWriter.apply(proxy.time);\n            outputWriter.apply(proxy.time);\n            cursor.style.opacity = proxy.time < 100 / 30 ? (Math.floor(proxy.time * 2) % 2 === 0 ? \"1\" : \"0\") : \"0\";\n          },\n        }, 0);\n        registerTimeline(\"cli-simulation\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
