    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"target\",\"type\":\"number\",\"label\":\"Target\",\"default\":1000}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0b1220;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0b1220;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #0b1220;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root { background-color: #0b1220; }\n      #stage { position: absolute; inset: 0; }\n      #value {\n        position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;\n        color: #f8fafc; font-weight: 800; font-variant-numeric: tabular-nums; z-index: 2;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"counter-confetti\"\n      data-start=\"0\"\n      data-duration=\"6\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"6\"></canvas>\n      <div id=\"value\" class=\"clip\" data-start=\"0\" data-duration=\"6\">0</div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const view = hyperbits.viewport();\n        const canvas = document.getElementById(\"stage\");\n        const valueEl = document.getElementById(\"value\");\n        canvas.width = view.width;\n        canvas.height = view.height;\n        valueEl.style.fontSize = view.vmin * 14 + \"px\";\n        const counter = hyperbits.createCounter(valueEl, { separator: \",\" });\n        const simulator = hyperbits.createParticles({\n          fps: 30,\n          spawners: [\n            {\n              id: \"left\",\n              burst: 80,\n              startFrame: 70,\n              position: { x: view.width * 0.15, y: view.height * 0.5 },\n              velocity: { x: 18, y: -8, varianceX: 10, varianceY: 16 },\n              lifespan: 50,\n              lifespanVariance: 10,\n            },\n            {\n              id: \"right\",\n              burst: 80,\n              startFrame: 70,\n              position: { x: view.width * 0.85, y: view.height * 0.5 },\n              velocity: { x: -18, y: -8, varianceX: 10, varianceY: 16 },\n              lifespan: 50,\n              lifespanVariance: 10,\n            },\n          ],\n          behaviors: [\n            { id: \"gravity\", handler: hyperbits.createGravity({ y: 0.35 }) },\n            { id: \"drag\", handler: hyperbits.createDrag(0.985) },\n            { id: \"fade\", handler: hyperbits.createOpacityOverLife([1, 0]) },\n            { id: \"scale\", handler: hyperbits.createScaleOverLife(1, 0.4) },\n          ],\n        });\n        const timeline = gsap.timeline({ paused: true });\n        timeline.fromTo(\n          counter.proxy,\n          { value: 0 },\n          { value: Number(vars.target) || 1000, duration: 3.2, ease: \"power2.out\", onUpdate: counter.apply },\n          0.2,\n        );\n        hyperbits.bind(timeline, canvas, simulator, { color: \"#f59e0b\", size: view.vmin * 1.2 });\n        timeline.to(valueEl, { scale: 1.06, duration: 0.45, yoyo: true, repeat: 5, ease: \"sine.inOut\" }, 3.4);\n        timeline.to({}, { duration: 6 }, 0);\n        registerTimeline(\"counter-confetti\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
