    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"words\",\"type\":\"string\",\"label\":\"Words (comma separated)\",\"default\":\"INITIALIZING,LOADING ASSETS,SYSTEM ONLINE,WELCOME USER\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #020617;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #020617;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #020617;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root {\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        background-color: #020617;\n      }\n      #title {\n        color: #4ade80;\n        font-family: ui-monospace, monospace;\n        font-weight: 700;\n        letter-spacing: 0.14em;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"glitch-cycle\"\n      data-start=\"0\"\n      data-duration=\"8\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <h1 id=\"title\" class=\"clip\" data-start=\"0\" data-duration=\"8\">INITIALIZING</h1>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const view = hyperbits.viewport();\n        const title = document.getElementById(\"title\");\n        const words = String(vars.words).split(\",\").map(function (part) { return part.trim(); }).filter(Boolean);\n        title.style.fontSize = view.vmin * 6 + \"px\";\n        const glyphs = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789#$\";\n        const itemDuration = 2;\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        function renderCycle() {\n          const time = proxy.time;\n          const index = Math.min(words.length - 1, Math.floor(time / itemDuration));\n          const local = time - index * itemDuration;\n          const target = words[index];\n          const glitchWindow = 0.35;\n          if (local < glitchWindow) {\n            const mix = local / glitchWindow;\n            let output = \"\";\n            for (let charIndex = 0; charIndex < target.length; charIndex += 1) {\n              if (hyperbits.random(\"cycle-\" + index + \"-\" + charIndex + \"-\" + Math.floor(mix * 12)) < mix) {\n                output += target[charIndex];\n              } else {\n                output += glyphs[hyperbits.randomInt(\"g-\" + index + \"-\" + charIndex + \"-\" + Math.floor(local * 20), 0, glyphs.length - 1)];\n              }\n            }\n            title.textContent = output;\n          } else {\n            title.textContent = target;\n          }\n        }\n        timeline.to(proxy, { time: 8, duration: 8, ease: \"none\", onUpdate: renderCycle }, 0);\n        registerTimeline(\"glitch-cycle\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
