    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Color\",\"default\":\"#00FF41\"},{\"id\":\"fontSize\",\"type\":\"number\",\"label\":\"Font size\",\"default\":30},{\"id\":\"speed\",\"type\":\"number\",\"label\":\"Speed\",\"default\":1},{\"id\":\"density\",\"type\":\"number\",\"label\":\"Density\",\"default\":1}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #000000;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #000000;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #000000;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root { background-color: #000000; }\n      #rain {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"matrix-rain\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <canvas id=\"rain\" class=\"clip\" data-start=\"0\" data-duration=\"10\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const view = hyperbits.viewport();\n        const canvas = document.getElementById(\"rain\");\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const fontSize = Number(vars.fontSize) || 30;\n        const columns = Math.max(1, Math.floor((view.width / fontSize) * Number(vars.density || 1)));\n        const glyphs = \"アイウエオカキクケコｱｲｳｴｵ0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\";\n        const drops = [];\n        for (let index = 0; index < columns; index += 1) {\n          drops.push({\n            y: hyperbits.randomFloat(\"drop-y-\" + index, -20, view.height / fontSize),\n            speed: hyperbits.randomFloat(\"drop-s-\" + index, 0.4, 1.4) * Number(vars.speed || 1),\n            length: hyperbits.randomInt(\"drop-l-\" + index, 8, 22),\n          });\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        function draw() {\n          context.fillStyle = \"#000000\";\n          context.fillRect(0, 0, canvas.width, canvas.height);\n          context.font = fontSize + \"px ui-monospace, monospace\";\n          for (let index = 0; index < drops.length; index += 1) {\n            const drop = drops[index];\n            const head = (drop.y + proxy.time * drop.speed * 18) % (view.height / fontSize + drop.length);\n            for (let trail = 0; trail < drop.length; trail += 1) {\n              const glyph = glyphs[hyperbits.randomInt(\"g-\" + index + \"-\" + trail, 0, glyphs.length - 1)];\n              const alpha = 1 - trail / drop.length;\n              context.fillStyle = trail === 0 ? \"#e7ffe7\" : vars.color;\n              context.globalAlpha = Math.max(0.12, alpha);\n              context.fillText(glyph, index * fontSize, (head - trail) * fontSize);\n            }\n          }\n          context.globalAlpha = 1;\n        }\n        timeline.to(proxy, { time: 10, duration: 10, ease: \"none\", onUpdate: draw }, 0);\n        registerTimeline(\"matrix-rain\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
