    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0b1220;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0b1220;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        background-color: #0b1220;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #root {\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        background-color: #0b1220;\n        color: #f8fafc;\n      }\n      #row { display: flex; }\n      .stat { display: flex; flex-direction: column; align-items: center; }\n      .ring-wrap { position: relative; }\n      .value {\n        position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;\n        font-weight: 700; font-variant-numeric: tabular-nums;\n      }\n      .label { color: #94a3b8; font-weight: 600; }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"stat-rings\"\n      data-start=\"0\"\n      data-duration=\"4\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"row\" class=\"clip\" data-start=\"0\" data-duration=\"4\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const view = hyperbits.viewport();\n        const row = document.getElementById(\"row\");\n        row.style.gap = view.vmin * 8 + \"px\";\n        const stats = [\n          { label: \"Uptime\", value: 99.9, decimals: 1 },\n          { label: \"Test coverage\", value: 87, decimals: 0 },\n          { label: \"Cache hits\", value: 64, decimals: 0 },\n        ];\n        const ringSize = view.vmin * 34;\n        const strokeWidth = view.vmin * 2.6;\n        const radius = (ringSize - strokeWidth) / 2;\n        const circumference = 2 * Math.PI * radius;\n        const rings = [];\n        stats.forEach(function (stat) {\n          const card = document.createElement(\"div\");\n          card.className = \"stat\";\n          const wrap = document.createElement(\"div\");\n          wrap.className = \"ring-wrap\";\n          wrap.style.width = ringSize + \"px\";\n          wrap.style.height = ringSize + \"px\";\n          const svg = document.createElementNS(\"http://www.w3.org/2000/svg\", \"svg\");\n          svg.setAttribute(\"width\", String(ringSize));\n          svg.setAttribute(\"height\", String(ringSize));\n          svg.setAttribute(\"viewBox\", \"0 0 \" + ringSize + \" \" + ringSize);\n          function circle(color, dash) {\n            const node = document.createElementNS(\"http://www.w3.org/2000/svg\", \"circle\");\n            node.setAttribute(\"cx\", String(ringSize / 2));\n            node.setAttribute(\"cy\", String(ringSize / 2));\n            node.setAttribute(\"r\", String(radius));\n            node.setAttribute(\"fill\", \"none\");\n            node.setAttribute(\"stroke\", color);\n            node.setAttribute(\"stroke-width\", String(strokeWidth));\n            node.setAttribute(\"stroke-linecap\", \"round\");\n            node.setAttribute(\"transform\", \"rotate(-90 \" + ringSize / 2 + \" \" + ringSize / 2 + \")\");\n            node.setAttribute(\"stroke-dasharray\", String(circumference));\n            node.setAttribute(\"stroke-dashoffset\", String(dash));\n            svg.append(node);\n            return node;\n          }\n          circle(\"#1e293b\", 0);\n          const arc = circle(\"#38bdf8\", circumference);\n          const valueEl = document.createElement(\"div\");\n          valueEl.className = \"value\";\n          valueEl.style.fontSize = view.vmin * 5 + \"px\";\n          const counter = hyperbits.createCounter(valueEl, { decimals: stat.decimals, postfix: \"%\" });\n          wrap.append(svg, valueEl);\n          const label = document.createElement(\"div\");\n          label.className = \"label\";\n          label.textContent = stat.label;\n          label.style.fontSize = view.vmin * 2.4 + \"px\";\n          label.style.marginTop = view.vmin * 2 + \"px\";\n          card.append(wrap, label);\n          row.append(card);\n          rings.push({ arc: arc, counter: counter, value: stat.value });\n        });\n        const timeline = gsap.timeline({ paused: true });\n        hyperbits.stagger(row.children, { opacity: [0, 1], scale: [0.6, 1], duration: 1, stagger: 12 / 30, delay: 5 / 30, ease: \"spring\" }, timeline);\n        rings.forEach(function (item, index) {\n          const delay = (20 + index * 12) / 30;\n          const proxy = { progress: 0 };\n          timeline.fromTo(\n            proxy,\n            { progress: 0 },\n            {\n              progress: item.value / 100,\n              duration: 2,\n              ease: \"power2.out\",\n              onUpdate: function () {\n                item.arc.setAttribute(\"stroke-dashoffset\", String(circumference * (1 - proxy.progress)));\n                item.counter.proxy.value = proxy.progress * 100;\n                item.counter.apply();\n              },\n            },\n            delay,\n          );\n        });\n        registerTimeline(\"stat-rings\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
